        vm.assume(putAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(putAmount >= collectAmount);
        vm.assume(warpDelta > 0);
        vm.assume(_unlockTime < type(uint256).max);
        address user = address(0x1234);
        vm.deal(user, putAmount);
        vm.prank(user);
        c.Put{value: putAmount}(_unlockTime);
        uint256 balBefore = c.Acc(user).balance;
        vm.warp(block.timestamp + warpDelta);
