pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 prevBalance, uint128 depositValue) public {
        // Keep prevBalance large enough to force overflow on addition
        vm.assume(prevBalance > type(uint256).max - type(uint128).max);
        vm.bound(depositValue, 1, type(uint128).max);

        // Add an address for the sender
        address sender = address(uint160(prevBalance) ^ uint160(depositValue));
        vm.assume(sender != address(0) && sender != address(this));

        // Set up the holder state with a large previous balance
        vm.assume(prevBalance >= 1 ether);
        vm.deal(sender, depositValue + 1 ether);
        vm.startPrank(sender);
        // First put to set the high balance
        c.Put{value: 1 ether}(block.timestamp);
        // Wipe the previous record and re-set to exactly prevBalance via direct state manipulation is forbidden,
        // so we just rely on making the second put overflow. We'll put another large amount so that total
        // of the two deposits is huge. But we need prevBalance exactly controlled, which we can't directly set.
        // Instead, we make prevBalance the result of the first deposit and add msg.value to it.
        // Actually we can just make the first Put with a value that is prevBalance - we're limited by deal.
        vm.stopPrank();

        // Reset: use a fresh sender to have zero starting balance; deploy a helper that will overflow the balance.
        address sender2 = address(uint160(uint256(keccak256(abi.encode(sender)))));
        vm.assume(sender2 != address(0) && sender2 != address(this) && sender2 != sender);
        vm.deal(sender2, prevBalance);
        vm.startPrank(sender2);
        // Initial Put to set balance to prevBalance
        c.Put{value: prevBalance}(block.timestamp);
        // Now add depositValue via another Put; the resulting balance would be prevBalance + depositValue.
        // In the reference, safe add ensures it stays correct; in the bug, it may overflow.
        uint256 msgValue = uint256(depositValue);
        vm.deal(sender2, msgValue);
        c.Put{value: msgValue}(block.timestamp);
        vm.stopPrank();

        // The balance after the second Put.
        (, uint256 storedBalance) = c.Acc(sender2);
        // Property: stored balance must be >= depositValue (since it includes depositValue).
        // If overflow occurs, storedBalance could be less than depositValue.
        assertTrue(storedBalance >= msgValue, "invariant violated: balance >= last deposit");
